  /* 現在ページ判定用にパスを正規化(/index.html と / を同一視、クエリ・ハッシュ除去) */
  function normPath(p){
    p = (p||'').split('#')[0].split('?')[0];
    p = p.replace(/\/index\.html$/,'/');
    return p;
  }
  var HERE = normPath(location.pathname);

  function itemLink(it, grIcon){
    var d = B + '/';
    var href = d + it[0];
    var cur = normPath(href) === HERE;
    var desc = EN ? it[4] : it[3];
    var icon = it[5] || grIcon || 'article';
    return '<a class="nav-item'+(cur?' is-here':'')+'" href="'+href+'"'+(cur?' aria-current="page"':'')+'>'
      +'<span class="nav-ico">'+ic(icon)+'</span>'
      +'<span class="nav-txt"><span class="nav-it">'+esc(EN?it[2]:it[1])+'</span>'
      +(desc?'<span class="nav-id">'+esc(desc)+'</span>':'')+'</span></a>';
  }
  function genLinks(){
    var d = B + '/', out = '';
    for(var g=1; g<=16; g++){
      var href = d + 'stats/gen-' + (g<10?'0'+g:g) + '/index.html';
      var cur = normPath(href) === HERE;
      out += '<a class="nav-gen'+(cur?' is-here':'')+'" href="'+href+'"'+(cur?' aria-current="page"':'')+'><small>'+(EN?'Gen':'第')+'</small>'+g+(EN?'':'<small>世代</small>')+'</a>';
    }
    return '<div class="nav-gens">'+out+'</div>';
  }
  function catPanel(c){
    var d = B + '/';
    var html = '';
    c.groups.forEach(function(gr){
      html += '<div class="nav-grp'+(gr.gens?' nav-grp-gens':'')+'"><div class="nav-gh">'+esc(EN?gr.h[1]:gr.h[0])
        +(gr.sub?'<span class="nav-gs">'+esc(EN?gr.sub[1]:gr.sub[0])+'</span>':'')+'</div>';
      if(gr.gens) html += genLinks();
      else html += gr.items.map(function(it){ return itemLink(it, gr.icon); }).join('');
      html += '</div>';
    });
    if(c.all) html += '<a class="nav-all" href="'+d+c.href+'"><span>'+esc(EN?c.all[1]:c.all[0])+'</span>'+ic('arrow_forward')+'</a>';
    return html;
  }
  function catIsHere(c){
    var d = B + '/';
    var hit = false;
    c.groups.forEach(function(gr){
      if(gr.gens){ if(/\/stats\/gen-\d\d\/$/.test(HERE)) hit = true; return; }
      gr.items.forEach(function(it){ if(normPath(d+it[0]) === HERE) hit = true; });
    });
    return hit;
  }
